head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil05500";
scwin.default_props = "toolbar=no,location=no,status=no,menubar=no,scrollbars=yes,resizable=no,";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_fillGen();
        scwin.init_conds();
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil05500.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_when_27", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "entity.code"); })() !== (dma_irCalcList.get("month") ?? (() => { throw new Error("unresolved:" + "irCalcList.month"); })())); } }, { id: "c_otherwise_30", fn: function(){ return (!(((() => { throw new Error("unresolved:data:" + "entity.code"); })() !== (dma_irCalcList.get("month") ?? (() => { throw new Error("unresolved:" + "irCalcList.month"); })())))); } }, { id: "c_when_73_txt", fn: function(){ return ((dma_status.get("index") ?? (() => { throw new Error("unresolved:" + "status.index"); })())===0 || (dma_status.get("index") ?? (() => { throw new Error("unresolved:" + "status.index"); })())%7===0 || (() => { throw new Error("unresolved:data:" + "entity.holidayYN"); })()==='Y'); } }, { id: "c_when_74_txt", fn: function(){ return ((dma_status.get("index") ?? (() => { throw new Error("unresolved:" + "status.index"); })())%7===6); } }, { id: "c_otherwise_75", fn: function(){ return (!(((dma_status.get("index") ?? (() => { throw new Error("unresolved:" + "status.index"); })())===0 || (dma_status.get("index") ?? (() => { throw new Error("unresolved:" + "status.index"); })())%7===0 || (() => { throw new Error("unresolved:data:" + "entity.holidayYN"); })()==='Y') || ((dma_status.get("index") ?? (() => { throw new Error("unresolved:" + "status.index"); })())%7===6))); } }, { id: "c_when_85_txt", fn: function(){ return ((dma_status.get("index") ?? (() => { throw new Error("unresolved:" + "status.index"); })())%7===6); } }, { id: "c_otherwise_86", fn: function(){ return (!(((dma_status.get("index") ?? (() => { throw new Error("unresolved:" + "status.index"); })())%7===6))); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_25", entity: "dlt_monthArray", countIds: [], cells: [{ childId: "__rc0", fn: function (v, i) { return String(v("name")) + "월"; } }, { childId: "__rc1", fn: function (v, i) { return String(v("name")) + "월"; } }] },
        { genId: "c_foreach_70", entity: "dlt_irCalcListDateList", countIds: [], cells: [{ childId: "__rc2", fn: function (v, i) { return String(v("day")); } }] },
        { genId: "c_foreach_91", entity: "dlt_entityIrList", countIds: [], cells: [{ childId: "btn_SearchIRDetail", fn: function (v, i) { return String(v("comNm")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: entry_edge). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name slc_selectYear_onchange
 * @description slc_selectYear 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.slc_selectYear_onchange = async function(e){
    try {
        await scwin.iRCalc();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05500.slc_selectYear_onchange' }); }
};

/**
 * @method
 * @name btn_IRCalcMonth_onclick
 * @description btn_IRCalcMonth 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_IRCalcMonth_onclick = async function(e){
    try {
        await scwin.iRCalcMonth((String(((() => { throw new Error("unresolved:data:" + "entity.code"); })()) == null ? '' : ((() => { throw new Error("unresolved:data:" + "entity.code"); })())).indexOf('$' + '{') >= 0 ? '' : String(((() => { throw new Error("unresolved:data:" + "entity.code"); })()) == null ? '' : ((() => { throw new Error("unresolved:data:" + "entity.code"); })()))))

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05500.btn_IRCalcMonth_onclick' }); }
};

/**
 * @method
 * @name btn_SearchIRDetail_onclick
 * @description btn_SearchIRDetail 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_SearchIRDetail_onclick = async function(e){
    try {
        await scwin.searchIRDetail('' + dlt_entityIrList.getCellData(0, "irSeq") + '')
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldfil05500.btn_SearchIRDetail_onclick" });
    }
};

/**
 * @method
 * @name __ev_4_btn_SearchIRDetail_onclick
 * @description __ev_4_btn_SearchIRDetail 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.__ev_4_btn_SearchIRDetail_onclick = async function(e){
    try {
        await scwin.searchIRDetail('' + dlt_entityIrList.getCellData(0, "irSeq") + '')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05500.__ev_4_btn_SearchIRDetail_onclick' }); }
};

/**
 * @method
 * @name img_101_onclick
 * @description 「목록」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_101_onclick = async function(e){
    try {
        await scwin.goURL('registerIR')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05500.img_101_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_IRCalc
 * @description IRCalc 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_IRCalc = async function () {
    const sbmOptions = {
        id: "tx_fn_IRCalc",
        method: "post",
        action: "/list/supportIR.do",
        ref: "dma_IRCalcReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_GoURL
 * @description Go URL 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_GoURL = async function () {
    const sbmOptions = {
        id: "tx_fn_GoURL",
        method: "post",
        action: "/list/supportIR.do",
        ref: "dma_GoURLReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_SearchIRDetail
 * @description Search IRDetail 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_SearchIRDetail = async function () {
    const sbmOptions = {
        id: "tx_fn_SearchIRDetail",
        method: "post",
        action: "/list/supportIR.do",
        ref: "dma_SearchIRDetailReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_load_list
 * @description load list 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/list/supportIR.do?method=searchIR",
        ref: "dma_loadListReq",
        target: "dlt_entityIrList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name iRCalc
 * @description i RCalc 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.iRCalc = async function () {
    $c.util.getComponent('dma_IRCalcReq').set('method', 'searchIR');
    (document.SupportIRForm || { elements: [] }).target = "_self";
    await scwin.tx_fn_IRCalc();
};

/**
 * @method
 * @name iRCalcMonth
 * @description i RCalc Month 처리
 * @param {*} month month
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.iRCalcMonth = async function (month) {
    $c.util.getComponent('dma_IRCalcReq').set('selectMonth', month);
    await scwin.iRCalc();
};

/**
 * @method
 * @name goURL
 * @description go URL 처리
 * @param {*} method method
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goURL = async function (method) {
    if (method === 'registerIR') {
        $c.util.getComponent('dma_IRCalcReq').set('method', method);
        (document.SupportIRForm || { elements: [] }).target = "_self";
        await scwin.tx_fn_GoURL();
    }
};

/**
 * @method
 * @name searchIRDetail
 * @description search IRDetail 처리
 * @param {*} ir_seq ir_seq
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchIRDetail = async function (ir_seq) {
    const props = scwin.default_props + "width=567,height=302";
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    (function(){ throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + "about:blank", unresolved: "nav:" + "about:blank" }; })();
    $c.util.getComponent('dma_IRCalcReq').set('method', "searchIRDetail");
    $c.util.getComponent('dma_IRCalcReq').set('irSeq', ir_seq);
    (document.SupportIRForm || { elements: [] }).target = "detail_pop";
    await scwin.tx_fn_SearchIRDetail();
};
